  "risks": [
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "n=24 total units (mover Shapers) across four seasons; after splitting into cut-heavy and drive-heavy, each subgroup is likely too small for a well-powered comparison."
    },
    {
      "code": "CONFOUNDING",
      "text": "Movers are not randomly assigned; a player's move reason (system fit, decline) and the new team's play-type tendencies will confound the apparent portability."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "The number of Shapers with a clear majority of CUT or DRIVE initiations may be extremely low; the exposure of interest may be rare in the population."
    },
    {
      "code": "MEASURE_RELIABILITY",
      "text": "Play-type classification for low-usage players and the structural influence residual both carry measurement error that may dominate any signal in a small-sample design."
    },
    {
      "code": "OUTCOME_DERIVED_LABEL",
      "text": "Defining cut-heavy/drive-heavy based on a player's entire season or career, possibly including post-move data, would leak outcome information into the grouping variable."
    },
    {
      "code": "MECHANICAL_FLOOR",
      "text": "Cut-heavy Shapers already have very low usage and influence; their structural influence may be bounded near zero, creating an artificial floor that makes their role appear stable relative to drive-heavy Shapers."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.1,
    "untestable": 0.6,
    "artifact": 0.05,
    "uncertain": 0.2
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Difference in mean change of structural influence (L_pre) from pre-move season to post-move season between Shapers classified as cut-heavy (>=50% of initiations from CUT) and those classified as drive-heavy (>=50% from DRIVE), adjusting for pre-move influence and team-level offensive system indicators.",
    "unit": "Individual player-seasons for Shapers who changed teams between consecutive seasons, with at least 20 games and 200 possessions pre-move and post-move in each season.",
    "sample": "All Shaper movers from 2022-23 to 2025-26 identified via the project's role classifier; exclude mid-season trades (use off-season moves only). Expect ~24 players, of which perhaps 6-10 may meet the cut-heavy or drive-heavy criteria.",
    "power": "With an estimated 8 per group and assuming a realistic effect size of ~0.15 in structural influence change (similar to displacement effect sizes), power for a two-sample t-test at alpha 0.05 would be below 20%. To reach 80% power for a moderate effect (d=0.5), approximately 64 per group would be needed, far exceeding the available population.",
    "controls": "Pre-move L_pre, change in team offensive rating, categorical variable for new team's offensive system (e.g., share of possessions that are cuts/drives). Multiple matches per player (decoys) could be used to reduce noise, though that introduces its own complications.",
    "falsification": "A placebo test: compute the same measure for a set of decoy Shapers who did not move, pairing them to movers by pre-move characteristics; the cut-heavy vs drive-heavy difference should not appear pre-move or in the decoy sample.",
    "multiplicity": "Bonferroni correction for testing multiple thresholds of cut/drive heavy (e.g., 40%, 50%, 60%) and for examining other role categories as secondary analyses.",
    "decision_rule": "Two-sided Welch’s t-test on the between-group difference in mean L_pre change, with pre-registered alpha 0.05 and the pre-specified 50% threshold; any deviation from the threshold would be exploratory. Due to anticipated insufficient power, the test would be labeled as descriptive only.",
    "data_version": "NBA play-by-play and derived play-type possession records frozen as of 2026-08-08, including seasons 2022-23 through 2025-26 (2025-26 playoffs may be incomplete depending on freeze date). Pre-registration would lock the computation pipeline and player classification before unblinding the mover sample."
  }
}

